@startuml
class Faculty {
  +name : string
}
class Institute {
  +name : string
  +address : string
}
class Employee {
  +socialSecurityNumber : string
  +name : string
  +emailAddress : string
}
class ResearchStaff extends Employee {
  +fieldOfResearch : string
}
class AdministrativeStaff extends Employee {}
class ResearchAssistant extends ResearchStaff {
  +fieldOfResearch : string
}
class Lecturer extends ResearchAssistant {
}
class Course {
  +id : int
  +name : string
  +weeklyDuration : int
}
class Project {
  +name : string
  +startDate : date
  +endDate : date
  +hours : int
}

Faculty "1" *-- "1..*" Institute : is made up of
Faculty "1" -- "1" Employee : is headed by dean
University "1" -- "*" Employee : has total number of employees

ResearchAssistant "1..*" -- "1..*" Institute : is assigned to
ResearchAssistant "1" -- "*" Project : is involved in
Lecturer "1" -- "*" Course : teaches
@enduml

